"""Writes docs/moniker.md from the .moniker vocabularies. Usage: python3 tools/moniker-doc.py"""
import json

def fmt_range(m):
    lo, hi = m['range']
    return f"{lo} to {hi}"

out = ["# skyCaptain Moniker vocabulary", "",
       "Generated by `tools/moniker-doc.py` from `src/moniker/*.moniker`. Edit the `.moniker`",
       "files, not this page. The engine is Lumen's Moniker Core (`vendor/moniker/`); the",
       "adapter that works out the families below is `src/moniker/skycaptain.js`.", "",
       "Names keep at most `max_tokens` words, counting the noun. Heavier slots survive",
       "trimming, and survivors are put back in `slot_order`. When a name is already taken,",
       "trimmed words are promoted back in before a number is added.", ""]
families = {
    'time': 'sun elevation: below 0° twilight, below 8° golden, below 22° low, below 55° day, else high',
    'mood': 'brooding = density ≥ 270 and ambient ≤ 0.75; soft = ambient ≥ 1.25 and powder ≤ 0.5; luminous = silver lining ≥ 0.86 and density < 270',
    'windKm': 'drift distance, √(driftX² + driftZ²) km',
    'scene': 'visible shapes at strength ≥ 0.3: front + storm = squall; 2+ storms = storms; 1 storm; front; clear hole = clearing; haze sheet; cumulus field; else painted if any paint, else open',
}
for name, title, use in [('look', 'Look presets', 'Names looks (.wcx) in the Looks panel.'),
                         ('sky', 'Whole skies', 'Names sky .wcx files and HDRI exports.')]:
    d = json.load(open(f'src/moniker/skycaptain-{name}.moniker'))
    out += [f"## {title}: `{d['id']}@{d['version']}`", "", use, "",
            f"Noun: **{d['noun'] or '(from the scene slot)'}**. Max tokens: {d['max_tokens']}. "
            f"Order: {' → '.join(d['slot_order'])}.", "",
            "| Slot | Weight | Reads | Words |", "| --- | --- | --- | --- |"]
    for slot_name in d['slot_order']:
        s = d['slots'][slot_name]
        words = []
        for m in s['mappings']:
            key = fmt_range(m) if 'range' in m else m['value']
            words.append(f"{key}: {'**' + m['token'] + '**' if m['token'] else '(nothing)'}")
        reads = s['parameter'] + (f" ({families[s['parameter']]})" if s['parameter'] in families else '')
        req = ' (required)' if s.get('required') else ''
        out.append(f"| {slot_name}{req} | {s['weight']} | {reads} | {'; '.join(words)} |")
    if d.get('composites'):
        out += ["", "Composite nouns (replace the noun when every condition fires):", ""]
        for c in d['composites']:
            reqs = ', '.join(f"{k} = {' or '.join([v] if isinstance(v, str) else v)}" for k, v in c['requires'].items())
            out.append(f"- **{c['token']}**: {reqs}")
    out.append("")
open('docs/moniker.md', 'w').write('\n'.join(out))
print('\n'.join(out[:40]))
